const BREAK={Cyberspace:2,Windy:3,Snowy:3,Rainy:4,Sandstorm:4,Starfall:5,Heaven:5,Corruption:5,Singularity:5,Hell:6,Dreamspace:7,'Crimson Moon':8,Glitched:10,Null:1000,Cloudy:3,Downpour:4,Oceanic:50,Normal:1};
const ITEMS=['Coins','Lucky Potion','Speed Potion','Gear A','Gear B'];
const defaults={rolls:0,basicLuck:0,specialLuck:0,finalMultiplier:1,speed:1,biome:'Normal',dimension:'Isles of Luck',dayNight:'Day',recent:[],auras:{},inventory:{},spawns:[],lastSpawn:0};
let state=load();
function load(){try{return Object.assign({},defaults,JSON.parse(localStorage.getItem(KEY)||'{}'))}catch(e){return Object.assign({},defaults)}}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function fmt(n){return new Intl.NumberFormat('en-US').format(n)}
function totalLuck(){return ((1+state.basicLuck)+state.specialLuck)*state.finalMultiplier}
function toast(msg){const e=document.createElement('div');e.className='notice';e.textContent=msg;document.getElementById('notices').appendChild(e);setTimeout(function(){e.remove()},3200)}
function roll(){
 state.rolls++;
 const bonus=state.rolls%10===0?2:1;
 const finalLuck=(((1+state.basicLuck)*bonus)+state.specialLuck)*state.finalMultiplier;
 const eligible=AURAS.filter(function(a){
   if(a.crafted||a.fixed||a.exclusive)return false;
   if(a.nativeBiome&&a.nativeBiome===state.biome)return true;
   if(a.nativeBiome&&a.nativeBiome!==state.biome)return true;
   return true;
 }).map(function(a){
   const breakthrough=!!(a.nativeBiome&&a.nativeBiome!==state.biome&&BREAK[state.biome]>1);
   return {a:a,breakthrough:breakthrough,listValue:Math.max(1,Math.floor((a.rarity*(breakthrough?BREAK[state.biome]:1))/finalLuck))};
 }).filter(function(x){return x.listValue>1});
 let chosen=null;
 for(let i=0;i<eligible.length;i++){
   if(Math.floor(Math.random()*eligible[i].listValue)+1===1){chosen=eligible[i];break}
 }
 if(!chosen)chosen=eligible[eligible.length-1]||{a:AURAS[0],breakthrough:false};
 const result=chosen.a;
 state.auras[result.name]=(state.auras[result.name]||0)+1;
 state.recent.unshift({name:result.name,rarity:result.rarity,rolledRarity:result.rarity*(chosen.breakthrough?BREAK[state.biome]:1),breakthrough:chosen.breakthrough,bonus:bonus>1});
 state.recent=state.recent.slice(0,5);
 save();render();
 toast(chosen.breakthrough?'Breakthrough! '+result.name:(bonus>1?'Bonus Roll: 2x Luck':'Roll complete'));
}
function spawnItems(){state.spawns=[];for(let i=0;i<3;i++)state.spawns.push({id:String(Date.now())+i,name:ITEMS[Math.floor(Math.random()*ITEMS.length)],x:8+Math.random()*82,y:8+Math.random()*78});state.lastSpawn=Date.now();save();render()}
function collect(id){const item=state.spawns.find(function(x){return x.id===id});if(!item)return;state.spawns=state.spawns.filter(function(x){return x.id!==id});state.inventory[item.name]=(state.inventory[item.name]||0)+1;save();render();toast('Collected '+item.name)}
function maybeSpawn(){if(!state.lastSpawn||Date.now()-state.lastSpawn>=60000)spawnItems()}
function tab(name){toast(name+' tab is next — Roll is the current build target.')}
function render(){let recent=state.recent.length?state.recent.map(function(r,i){return '<div class="recent-row"><span><b>#'+fmt(state.rolls-i)+'</b> '+r.name+'</span><small>1/'+fmt(r.rarity)+'</small></div>'}).join(''):'<div class="empty">No rolls yet.</div>';let spawns=state.spawns.length?state.spawns.map(function(s){return '<button class="spawn" style="left:'+s.x+'%;top:'+s.y+'%" onclick="collect(\''+s.id+'\')">'+s.name+'</button>'}).join(''):'<div class="empty">Personal ground items will appear here.</div>';let inv=Object.keys(state.inventory).length?Object.entries(state.inventory).map(function(e){return '<div class="info"><span>'+e[0]+'</span><b>x'+e[1]+'</b></div>'}).join(''):'<div class="empty">Nothing collected.</div>';let last=state.recent[0]?'<div class="aura-name">'+state.recent[0].name+'</div><div class="rarity">1/'+fmt(state.recent[0].rolledRarity||state.recent[0].rarity)+(state.recent[0].breakthrough?' • BREAKTHROUGH':'')+(state.recent[0].bonus?' • BONUS ROLL':'')+'</div>':'<div class="rarity">Your next Aura appears here.</div>';document.getElementById('app').innerHTML='<div class="shell"><header class="topbar"><div class="logo">EQUINOX</div><div class="topstats"><span>Rolls <b>'+fmt(state.rolls)+'</b></span><span>Luck <b>'+state.luck.toFixed(2)+'x</b></span><span>Speed <b>'+state.speed.toFixed(2)+'x</b></span></div></header><div class="layout"><nav class="tabs"><button class="tab active" onclick="tab(\'Roll\')">◉ Roll</button><button class="tab" onclick="tab(\'Inventory\')">▣ Inventory</button><button class="tab" onclick="tab(\'NPCs\')">♙ NPCs</button><button class="tab" onclick="tab(\'Global\')">◎ Global</button><button class="tab" onclick="tab(\'Settings\')">⚙ Settings</button><button class="tab" onclick="tab(\'Achievements\')">★ Achievements</button></nav><main><div class="roll-grid"><section><div class="panel hero"><h1>ROLL FOR AN AURA</h1><button class="roll-btn" onclick="roll()">ROLL…</button><div class="last-result">'+last+'</div></div><div class="panel" style="margin-top:18px"><div class="section-title">Spawning Items</div><div class="spawn-area">'+spawns+'</div></div></section><aside class="panel"><div class="section-title">Recent Rolls</div><div class="recent">'+recent+'</div><div class="section-title" style="margin-top:22px">Current Stats</div><div class="stats"><div class="stat"><span>Total Luck</span><b>'+((((1+state.basicLuck)+state.specialLuck)*state.finalMultiplier)).toFixed(2)+'x</b></div><div class="stat"><span>Roll Speed</span><b>'+state.speed.toFixed(2)+'x</b></div></div></aside></div></main><aside class="side"><div class="section-title">World State</div><div class="info-list"><div class="info"><span>Biome</span><b>'+state.biome+'</b></div><div class="info"><span>Time</span><b>'+state.dayNight+'</b></div><div class="info"><span>Dimension</span><b>'+state.dimension+'</b></div><div class="info"><span>Total Rolls</span><b>'+fmt(state.rolls)+'</b></div></div><div class="section-title" style="margin-top:24px">Inventory Preview</div><div class="info-list">'+inv+'</div></aside></div><footer class="footer">Equinox • Roll tab foundation • Progress saved locally in this prototype.</footer><div id="notices" class="notice-stack"></div></div>'}
setInterval(maybeSpawn,1000);render();